description:
Write a macro `settings!` that defines a struct with default values and a "with" method per field:

```rust
settings! {
    Window {
        width: u32 = 800,
        height: u32 = 600,
        title: String = String::from("untitled"),
    }
}

let w = Window::default().with_width(1024).with_title("Game".into());
// w.width == 1024, w.height == 600, w.title == "Game"
```

The macro must produce:
- `#[derive(Debug, Clone, PartialEq)] struct Name { pub field: Type, ... }`;
- `impl Default for Name` using the given default expressions;
- for each field, a method `with_<field>(mut self, value: Type) -> Self` that sets it and returns `self`.

Method names are made by joining `with_` and the field name: since `macro_rules!` cannot join identifiers on its own, the macro receives the method names too, like this:

```rust
settings! {
    Window {
        width: u32 = 800 => with_width,
        height: u32 = 600 => with_height,
        title: String = String::from("untitled") => with_title,
    }
}
```

solution.solution.rs:
macro_rules! settings {
    ($name:ident { $($field:ident : $ty:ty = $default:expr => $with:ident),* $(,)? }) => {
        #[derive(Debug, Clone, PartialEq)]
        struct $name {
            $(pub $field: $ty,)*
        }

        impl Default for $name {
            fn default() -> Self {
                $name { $($field: $default,)* }
            }
        }

        impl $name {
            $(
                fn $with(mut self, value: $ty) -> Self {
                    self.$field = value;
                    self
                }
            )*
        }
    };
}

unitTests:
settings! {
    Window {
        width: u32 = 800 => with_width,
        height: u32 = 600 => with_height,
        title: String = String::from("untitled") => with_title,
    }
}

settings! {
    Audio { volume: f32 = 0.8 => with_volume }
}

test("defaults", || {
    let w = Window::default();
    check_eq(w.width, 800);
    check_eq(w.height, 600);
    check_eq(w.title.as_str(), "untitled");
    check_eq(Audio::default().volume, 0.8);
});

test("with methods", || {
    let w = Window::default().with_width(1024).with_title("Game".into());
    check_eq((w.width, w.height, w.title.clone()), (1024, 600, String::from("Game")));
    check_eq(Audio::default().with_volume(0.25), Audio { volume: 0.25 });
});

